/**
 * @ingroup     sys_ztimer
 * @{
 *
 * @file
 * @brief       ztimer core functionality
 *
 * This file contains ztimer's main API implementation and functionality
 * present in all ztimer clocks (most notably multiplexing ant extension).
 *
 * @author      Kaspar Schleiser <kaspar@schleiser.de>
 *
 * @}
 */
#include <assert.h>
#include <stdint.h>
#include <inttypes.h>

#include "kernel_defines.h"
#include "irq.h"
#ifdef MODULE_PM_LAYERED
#include "pm_layered.h"
#endif
#include "ztimer.h"

#define ENABLE_DEBUG 0
#include "debug.h"

static void _add_entry_to_list(ztimer_clock_t *clock, ztimer_base_t *entry);
static bool _del_entry_from_list(ztimer_clock_t *clock, ztimer_base_t *entry);
static void _ztimer_update(ztimer_clock_t *clock);
static void _ztimer_print(const ztimer_clock_t *clock);
static uint32_t _ztimer_update_head_offset(ztimer_clock_t *clock);

#ifdef MODULE_ZTIMER_EXTEND
static inline uint32_t _min_u32(uint32_t a, uint32_t b)
{
    return a < b ? a : b;
}
#endif

static unsigned _is_set(const ztimer_clock_t *clock, const ztimer_t *t)
{
    if (!clock->list.next) {
        return 0;
    }
    else {
        return (t->base.next || &t->base == clock->last);
    }
}

unsigned ztimer_is_set(const ztimer_clock_t *clock, const ztimer_t *timer)
{
    unsigned state = irq_disable();
    unsigned res = _is_set(clock, timer);

    irq_restore(state);
    return res;
}

bool ztimer_remove(ztimer_clock_t *clock, ztimer_t *timer)
{
    bool was_removed = false;
    unsigned state = irq_disable();

    if (_is_set(clock, timer)) {
        _ztimer_update_head_offset(clock);
        was_removed = _del_entry_from_list(clock, &timer->base);

        _ztimer_update(clock);
    }

    irq_restore(state);
    return was_removed;
}

uint32_t ztimer_set(ztimer_clock_t *clock, ztimer_t *timer, uint32_t val)
{
    DEBUG("ztimer_set(): %p: set %p at %" PRIu32 " offset %" PRIu32 "\n",
          (void *)clock, (void *)timer, clock->ops->now(clock), val);

    unsigned state = irq_disable();

    uint32_t now = _ztimer_update_head_offset(clock);

    if (_is_set(clock, timer)) {
        _del_entry_from_list(clock, &timer->base);
    }

    /* optionally subtract a configurable adjustment value */
    if (val > clock->adjust_set) {
        val -= clock->adjust_set;
    }
    else {
        val = 0;
    }

    timer->base.offset = val;
    _add_entry_to_list(clock, &timer->base);
    if (clock->list.next == &timer->base) {
#ifdef MODULE_ZTIMER_EXTEND
        if (clock->max_value < UINT32_MAX) {
            val = _min_u32(val, clock->max_value >> 1);
        }
        DEBUG("ztimer_set(): %p setting %" PRIu32 "\n", (void *)clock, val);
#endif
        clock->ops->set(clock, val);
    }

    irq_restore(state);
    return now;
}

static void _add_entry_to_list(ztimer_clock_t *clock, ztimer_base_t *entry)
{
    uint32_t delta_sum = 0;

    ztimer_base_t *list = &clock->list;

#ifdef MODULE_PM_LAYERED
    /* First timer on the clock's linked list */
    if (list->next == NULL &&
        clock->block_pm_mode != ZTIMER_CLOCK_NO_REQUIRED_PM_MODE) {
        pm_block(clock->block_pm_mode);
    }
#endif

    /* Jump past all entries which are set to an earlier target than the new entry */
    while (list->next) {
        ztimer_base_t *list_entry = list->next;
        if ((list_entry->offset + delta_sum) > entry->offset) {
            break;
        }
        delta_sum += list_entry->offset;
        list = list->next;
    }

    /* Insert into list */
    entry->next = list->next;
    entry->offset -= delta_sum;
    if (entry->next) {
        entry->next->offset -= entry->offset;
    }
    else {
        clock->last = entry;
    }
    list->next = entry;
    DEBUG("_add_entry_to_list() %p offset %" PRIu32 "\n", (void *)entry,
          entry->offset);

}

static uint32_t _add_modulo(uint32_t a, uint32_t b, uint32_t mod)
{
    if (a < b) {
        a += mod + 1;
    }
    return a - b;
}

#ifdef MODULE_ZTIMER_EXTEND
ztimer_now_t _ztimer_now_extend(ztimer_clock_t *clock)
{
    assert(clock->max_value);
    unsigned state = irq_disable();
    uint32_t lower_now = clock->ops->now(clock);

    DEBUG(
        "ztimer_now() checkpoint=%" PRIu32 " lower_last=%" PRIu32
        " lower_now=%" PRIu32 " diff=%" PRIu32 "\n",
        (uint32_t)clock->checkpoint, clock->lower_last, lower_now,
        _add_modulo(lower_now, clock->lower_last, clock->max_value));
    clock->checkpoint += _add_modulo(lower_now, clock->lower_last,
                                     clock->max_value);
    clock->lower_last = lower_now;
    DEBUG("ztimer_now() returning %" PRIu32 "\n", (uint32_t)clock->checkpoint);
    ztimer_now_t now = clock->checkpoint;

    irq_restore(state);
    return now;
}
#endif /* MODULE_ZTIMER_EXTEND */

static uint32_t _ztimer_update_head_offset(ztimer_clock_t *clock)
{
    uint32_t old_base = clock->list.offset;
    uint32_t now = ztimer_now(clock);
    uint32_t diff = now - old_base;

    ztimer_base_t *entry = clock->list.next;

    DEBUG(
        "clock %p: _ztimer_update_head_offset(): diff=%" PRIu32 " old head %p\n",
        (void *)clock, diff, (void *)entry);
    if (entry) {
        do {
            if (diff <= entry->offset) {
                entry->offset -= diff;
                break;
            }
            else {
                diff -= entry->offset;
                entry->offset = 0;
                if (diff) {
                    /* skip timers with offset==0 */
                    do {
                        entry = entry->next;
                    } while (entry && (entry->offset == 0));
                }
            }
        } while (diff && entry);
        DEBUG(
            "ztimer %p: _ztimer_update_head_offset(): now=%" PRIu32 " new head %p",
            (void *)clock, now, (void *)entry);
        if (entry) {
            DEBUG(" offset %" PRIu32 "\n", entry->offset);
        }
        else {
            DEBUG("\n");
        }
    }

    clock->list.offset = now;
    return now;
}

static bool _del_entry_from_list(ztimer_clock_t *clock, ztimer_base_t *entry)
{
    bool was_removed = false;

    DEBUG("_del_entry_from_list()\n");
    ztimer_base_t *list = &clock->list;

    assert(_is_set(clock, (ztimer_t *)entry));

    while (list->next) {
        ztimer_base_t *list_entry = list->next;
        if (list_entry == entry) {
            if (entry == clock->last) {
                /* if entry was the last timer, set the clocks last to the
                 * previous entry, or NULL if that was the list ptr */
                clock->last = (list == &clock->list) ? NULL : list;
            }

            list->next = entry->next;
            if (list->next) {
                list_entry = list->next;
                list_entry->offset += entry->offset;
            }

            was_removed = true;
            /* reset the entry's next pointer so _is_set() considers it unset */
            entry->next = NULL;
            break;
        }
        list = list->next;
    }

#ifdef MODULE_PM_LAYERED
    /* The last timer just got removed from the clock's linked list */
    if (clock->list.next == NULL &&
        clock->block_pm_mode != ZTIMER_CLOCK_NO_REQUIRED_PM_MODE) {
        pm_unblock(clock->block_pm_mode);
    }
#endif

    return was_removed;
}

static ztimer_t *_now_next(ztimer_clock_t *clock)
{
    ztimer_base_t *entry = clock->list.next;

    if (entry && (entry->offset == 0)) {
        clock->list.next = entry->next;
        if (!entry->next) {
            /* The last timer just got removed from the clock's linked list */
            clock->last = NULL;
#ifdef MODULE_PM_LAYERED
            if (clock->block_pm_mode != ZTIMER_CLOCK_NO_REQUIRED_PM_MODE) {
                pm_unblock(clock->block_pm_mode);
            }
#endif
        }
        else {
            /* reset next pointer so ztimer_is_set() works */
            entry->next = NULL;
        }
        return (ztimer_t *)entry;
    }
    else {
        return NULL;
    }
}

static void _ztimer_update(ztimer_clock_t *clock)
{
#ifdef MODULE_ZTIMER_EXTEND
    if (clock->max_value < UINT32_MAX) {
        if (clock->list.next) {
            clock->ops->set(clock,
                            _min_u32(clock->list.next->offset,
                                     clock->max_value >> 1));
        }
        else {
            clock->ops->set(clock, clock->max_value >> 1);
        }
#else
    if (0) {
#endif
    }
    else {
        if (clock->list.next) {
            clock->ops->set(clock, clock->list.next->offset);
        }
        else {
            if (IS_USED(MODULE_ZTIMER_NOW64)) {
                /* ensure there's at least one ISR per half period */
                clock->ops->set(clock, clock->max_value >> 1);
            }
            else {
                clock->ops->cancel(clock);
            }
        }
    }
}

void ztimer_handler(ztimer_clock_t *clock)
{
    DEBUG("ztimer_handler(): %p now=%" PRIu32 "\n", (void *)clock, clock->ops->now(
              clock));
    if (IS_ACTIVE(ENABLE_DEBUG)) {
        _ztimer_print(clock);
    }

#if MODULE_ZTIMER_EXTEND || MODULE_ZTIMER_NOW64
    if (IS_USED(MODULE_ZTIMER_NOW64) || clock->max_value < UINT32_MAX) {
        /* calling now triggers checkpointing */
        uint32_t now = ztimer_now(clock);

        if (clock->list.next) {
            uint32_t target = clock->list.offset + clock->list.next->offset;
            int32_t diff = (int32_t)(target - now);
            if (diff > 0) {
                DEBUG("ztimer_handler(): %p postponing by %" PRIi32 "\n",
                      (void *)clock, diff);
                clock->ops->set(clock, _min_u32(diff, clock->max_value >> 1));
                return;
            }
            else {
                DEBUG("ztimer_handler(): %p diff=%" PRIi32 "\n", (void *)clock,
                      diff);
            }
        }
        else {
            DEBUG("ztimer_handler(): %p intermediate\n", (void *)clock);
            clock->ops->set(clock, clock->max_value >> 1);
            return;
        }
    }
    else {
        DEBUG("ztimer_handler(): no checkpointing\n");
    }
#endif

    if (clock->list.next) {
        clock->list.offset += clock->list.next->offset;
        clock->list.next->offset = 0;

        ztimer_t *entry = _now_next(clock);
        while (entry) {
            DEBUG("ztimer_handler(): trigger %p->%p at %" PRIu32 "\n",
                  (void *)entry, (void *)entry->base.next, clock->ops->now(
                      clock));
            entry->callback(entry->arg);
            entry = _now_next(clock);
            if (!entry) {
                /* See if any more alarms expired during callback processing */
                /* This reduces the number of implicit calls to clock->ops->now() */
                _ztimer_update_head_offset(clock);
                entry = _now_next(clock);
            }
        }
    }

    _ztimer_update(clock);

    if (IS_ACTIVE(ENABLE_DEBUG)) {
        _ztimer_print(clock);
    }
    DEBUG("ztimer_handler(): %p done.\n", (void *)clock);
    if (!irq_is_in()) {
        thread_yield_higher();
    }
}

static void _ztimer_print(const ztimer_clock_t *clock)
{
    const ztimer_base_t *entry = &clock->list;
    uint32_t last_offset = 0;

    do {
        printf("0x%08x:%" PRIu32 "(%" PRIu32 ")%s", (unsigned)entry,
               entry->offset, entry->offset +
               last_offset,
               entry->next ? "->" : (entry == clock->last ? "" : "!"));
        last_offset += entry->offset;

    } while ((entry = entry->next));
    puts("");
}

messages.content:
Now let me think about the implementation carefully.

Looking at `test_ztimer_ondemand_timers`:
```c
ztimer_mock_init(&zmock, 32);
z->adjust_clock_start = 10;

int a_arg = 0;
ztimer_t a = {.callback = _set_cb, .arg = &a_arg};
const uint32_t a_val = 100;
ztimer_set(z, &a, a_val);
TEST_ASSERT_EQUAL_INT(a_val - z->adjust_clock_start, zmock.target);  // 90
TEST_ASSERT_EQUAL_INT(1, zmock.running);
TEST_ASSERT_EQUAL_INT(1, zmock.armed);
```

So when `ztimer_set` is called and there are no current users (no timers active), it should auto-acquire (start) the clock, and apply `adjust_clock_start` to the timer value. The target should be `100 - 10 = 90`.

But wait, `adjust_set` is already subtracted. Let me check what `adjust_set` is set to. In the test, only `adjust_clock_start` is set. `adjust_set` would be 0 (from memset/init). So the value 100 goes through, and `adjust_clock_start` should be subtracted... but where?

Looking at the test assertion: `zmock.target == a_val - z->adjust_clock_start == 90`. Since `adjust_set` is 0, the `val` after the adjust_set subtraction is still 100. Then the target set on the mock should be 90. So `adjust_clock_start` is subtracted from the val when setting the first timer after starting the clock.

Wait, but `adjust_clock_start` is supposed to account for the time it takes to start the clock. So when we start the clock, we know some time has already passed, so we subtract that from the first timer's target.

Looking at the implementation flow:
1. `ztimer_set` is called with val=100
2. Since list is empty (no timers), this is the first timer → auto-acquire → call start()
3. Subtract `adjust_clock_start` from val (100 - 10 = 90)
4. Set timer with val=90

Now for the converted timer test:
```c
ztimer_mock_init(&zmock, 24);
ztimer_convert_frac_init(&zc, &zmock.super, 1, 10);
z->adjust_clock_start = 10;

ztimer_set(z, &a, 100);
TEST_ASSERT_EQUAL_INT((100 - 10) * 10, zmock.target);  // 900
```

So `adjust_clock_start` is applied at the converted clock level (val 100 - 10 = 90), then the conversion applies (90 * 10 = 900).

OK, let me also look at the second timer in `test_ztimer_ondemand_timers`:
```c
int b_arg = 0;
ztimer_t b = {.callback = _set_cb, .arg = &b_arg};
const uint32_t b_val = 200;
uint32_t diff = zmock.target;  // 90 (from first timer)
ztimer_set(z, &b, b_val);  // b_val = 200

/* let the first timer fire */
ztimer_mock_advance(&zmock, zmock.target);
TEST_ASSERT_EQUAL_INT(HAS_BEEN_EXEC, a_arg);
TEST_ASSERT_EQUAL_INT(b_val - diff, zmock.target);  // 200 - 90 = 110
```

So when the second timer is set at time 0 with b_val=200, and the first timer was already set at target 90, after advancing 90 ticks, the first fires, and the remaining target for b should be 200 - 90 = 110. But the `adjust_clock_start` is NOT applied to the second timer (because the clock is already started).

Then:
```c
/* let the second timer fire -> no users left! */
ztimer_mock_advance(&zmock, zmock.target);
TEST_ASSERT_EQUAL_INT(HAS_BEEN_EXEC, b_arg);
TEST_ASSERT_EQUAL_INT(0, zmock.running);
TEST_ASSERT_EQUAL_INT(0, zmock.armed);
```

So when the last timer fires, the clock is auto-released and stopped.

Now let me also check: in the test `test_ztimer_ondemand_acquire_release`, after init with 32-bit, `running==0`. After acquire, `running==1, armed==0`. For 32-bit, `_ztimer_update` would call `cancel()` when no timers are set (no extension needed). But the test says `armed==0` not that cancel was called. The mock's cancel just sets `armed=0`, and the mock's start doesn't set armed. So this is fine.

Wait, but `ztimer_acquire` calls start() which sets running=1 but doesn't touch armed. Then for the extension: since it's 32-bit, no extension timer. So armed stays 0. Good.

For 24-bit `test_ztimer_ondemand_acquire_release_extend`: acquire → start() called → running=1. Then we need to set the extension timer. So `armed` becomes 1 (via `ztimer_init_extend`).

So `ztimer_acquire` should:
1. Increment `users`
2. If users goes from 0 to 1: call `start()` if available, then call `ztimer_init_extend()` if needed

And `ztimer_release` should:
1. Decrement `users`
2. If users goes to 0: call `cancel()` to clear any extension timer, then call `stop()` if available

Let me also check: in the `test_ztimer_ondemand_acquire_ops_unsupported` test with NULL start/stop:
```c
ztimer_acquire(z);
TEST_ASSERT_EQUAL_INT(0, zmock.calls.start);
TEST_ASSERT_EQUAL_INT(1, zmock.armed);  // extension timer set (24-bit)
```

So even without start(), acquire should still set the extension timer.

```c
ztimer_release(z);
TEST_ASSERT_EQUAL_INT(0, zmock.calls.stop);
TEST_ASSERT_EQUAL_INT(0, zmock.armed);  // extension timer cancelled
```

And release should cancel the extension timer even without stop().

Now let me also look at `_ztimer_update` more carefully for the ondemand case. When the last timer fires in `ztimer_handler`, `_ztimer_update` is called. For a 32-bit timer with no more entries, it calls `cancel()`. For an extended timer with no more entries, it calls `set(clock, max_value >> 1)` for extension. But with ondemand, we want to STOP the clock when all timers are done.

So I need to modify `_ztimer_update` for the ondemand case. When there are no more entries in the list AND ondemand is enabled AND no manual users (users == 0), we should stop the clock instead of setting extension timers.

Wait, but users tracks manual acquires. The auto-acquire from `ztimer_set` doesn't increment users. Let me reconsider.

Actually, looking at the test `test_ztimer_ondemand_timers`:
- `ztimer_set(z, &a, a_val)` → clock starts (running=1, armed=1)
- After `a` fires and `b` fires → running=0, armed=0
- There are no explicit `ztimer_acquire` calls

And `test_ztimer_mock_set16`:
- `ztimer_acquire(z)` is called explicitly
- Timers are set and fire
